/* ---- drawing helpers for this lesson (prefixed W6_ so nothing clashes with the engine) ---- */
const W6_F='font-family="Nunito Sans, sans-serif"';
const W6_T=(x,y,t,o={})=>`<text x="${(+x).toFixed(1)}" y="${(+y).toFixed(1)}" ${W6_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.ex?' '+o.ex:''}>${t}</text>`;
const W6_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${(+x1).toFixed(1)}" y1="${(+y1).toFixed(1)}" x2="${(+x2).toFixed(1)}" y2="${(+y2).toFixed(1)}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const W6_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.ex?' '+o.ex:''}/>`;
const W6_head=(x2,y2,a,col,h=14)=>`<polygon points="${x2.toFixed(1)},${y2.toFixed(1)} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`;
const W6_arrow=(x1,y1,x2,y2,col='#18213A',w=3,h=14)=>{const a=Math.atan2(y2-y1,x2-x1);return W6_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+W6_head(x2,y2,a,col,h)};
/* a double-headed polarization arrow at angle th (degrees from vertical) centred on (x,y) */
const W6_pol=(x,y,th,col,L=30)=>{const r=th*Math.PI/180,dx=L*Math.sin(r),dy=-L*Math.cos(r);return W6_arrow(x,y,x+dx,y+dy,col,3,12)+W6_arrow(x,y,x-dx,y-dy,col,3,12)};
const W6_GREY='#5C6577', W6_CORE='#DBE4FF', W6_CLAD='#F1F3F5';
const W6_sub=t=>`<tspan\tbaseline-shift="-0.2em"\tfont-size="72%">${t}</tspan>`;
const W6_sup=t=>`<tspan\tbaseline-shift="super"\tfont-size="70%">${t}</tspan>`;
/* the book's numbers, computed once */
const W6_dl=lnm=>Math.pow(lnm*1e-9,2)*1e11/3e8*1e9;           // nm per 100 GHz: 0.572 at 1310, 0.8008 at 1550, 0.864 at 1610
const W6_comb=(x0,y0,s,n,h,col,w=2)=>{let o='';for(let i=0;i<n;i++)o+=W6_L(x0+i*s,y0,x0+i*s,y0-h,i===0?GRN:col,w);return o};
/* a short piece of fiber core with a Bragg grating of pitch p px drawn between x0 and x1 */
const W6_grating=(x0,x1,y,h,p,col)=>{let o=`<rect x="${x0}" y="${y-h/2}" width="${x1-x0}" height="${h}" fill="${W6_CORE}" stroke="${BLU}" stroke-width="2"/>`;for(let x=x0+p/2;x<x1-2;x+=p)o+=`<rect x="${(x-p/4).toFixed(1)}" y="${y-h/2}" width="${(p/2).toFixed(1)}" height="${h}" fill="${col}" fill-opacity=".35"/>`;return o};

